const input = $input.first()?.json || {};
const context = input.context || {};

// Read image URL from root or nested context
const imageUrl =
  input.image_url ||
  input.photo_url ||
  context.image_url ||
  context.photo_url;

const description =
  input.description ||
  context.description ||
  input.message ||
  "";

const location =
  input.location ||
  context.location ||
  "";

if (!imageUrl) {
  throw new Error("Image URL is missing from Supervisor input.");
}

if (
  typeof imageUrl !== "string" ||
  !imageUrl.startsWith("https://")
) {
  throw new Error("A valid HTTPS image URL is required.");
}

const visionPrompt = `
You are the Vision Agent for CampusResolve.

Analyze the uploaded campus issue photograph.

Student description: ${description}
Campus location: ${location}

Identify:
1. What is visibly wrong?
2. What evidence is visible in the photograph?
3. Is there a recognizable campus issue?
4. Is manual verification required?

Rules:
- Do not invent problems.
- Do not assume damage that is not visible.
- Use the student description as additional context.
- If the image is unclear, request manual review.
- Return valid JSON only.

Required output:
{
  "issue_detected": true,
  "issue_description": "",
  "visible_evidence": "",
  "confidence": 0,
  "requires_manual_review": false
}
`;

return [{
  json: {
    ...input,
    image_url: imageUrl,
    description,
    location,
    vision_prompt: visionPrompt
  }
}];

const original = $("Prepare Image for Vision").first().json;
const result = $input.first().json;

function extractVision(data) {
  if (typeof data === "string") {
    const cleaned = data
      .replace(/^```json\s*/i, "")
      .replace(/\s*```$/i, "")
      .trim();

    try {
      return extractVision(JSON.parse(cleaned));
    } catch {
      return null;
    }
  }

  if (!data || typeof data !== "object") {
    return null;
  }

  if (
    Object.prototype.hasOwnProperty.call(data, "issue_detected") &&
    Object.prototype.hasOwnProperty.call(data, "issue_description")
  ) {
    return data;
  }

  for (const key of ["output", "text", "response", "result", "data"]) {
    if (data[key] !== undefined) {
      const extracted = extractVision(data[key]);
      if (extracted) return extracted;
    }
  }

  return null;
}

const vision = extractVision(result);

if (!vision) {
  throw new Error("Vision Agent did not return valid structured output.");
}

return [{
  json: {
    ...original,
    vision_analysis: vision,
    issue_detected: vision.issue_detected,
    issue_description: vision.issue_description,
    visible_evidence: vision.visible_evidence,
    confidence: vision.confidence,
    requires_manual_review: vision.requires_manual_review
  }
}];
